# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e293b">SÜTUN VE DAİRE GRAFİĞİ ARASINDA DÖNÜŞÜM (KAT VE MERKEZ AÇI YÖNTEMİ)</text>\n  <rect x="20" y="44" width="320" height="196" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="65" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Sütun Grafiğinden Daire Grafiğine Geçiş</text>\n  <text x="180" y="86" text-anchor="middle" font-size="11" fill="#1e3a8a">Örnek: Bir bahçedeki 90 ağacın dağılımı:</text>\n  <text x="180" y="106" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">Elma: 30 · Armut: 25 · Kiraz: 35 (Toplam = 90)</text>\n  <rect x="55" y="140" width="45" height="50" fill="#ef4444" rx="3"/>\n  <text x="77" y="135" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">30</text>\n  <text x="77" y="204" text-anchor="middle" font-size="10" fill="#1e293b">Elma</text>\n  <rect x="145" y="148" width="45" height="42" fill="#22c55e" rx="3"/>\n  <text x="167" y="143" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">25</text>\n  <text x="167" y="204" text-anchor="middle" font-size="10" fill="#1e293b">Armut</text>\n  <rect x="235" y="132" width="45" height="58" fill="#a855f7" rx="3"/>\n  <text x="257" y="127" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">35</text>\n  <text x="257" y="204" text-anchor="middle" font-size="10" fill="#1e293b">Kiraz</text>\n  <text x="180" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">Orantı: 90 ağaç → 360° ise 1 ağaç → 4° düşer!</text>\n\n  <rect x="360" y="44" width="320" height="196" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="65" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Daire Grafiği Merkez Açıları ve Kat Hesabı</text>\n  <text x="520" y="90" text-anchor="middle" font-size="11" fill="#14532d">• Elma Merkez Açısı: 30 x 4° = 120°</text>\n  <text x="520" y="112" text-anchor="middle" font-size="11" fill="#14532d">• Armut Merkez Açısı: 25 x 4° = 100°</text>\n  <text x="520" y="134" text-anchor="middle" font-size="11" fill="#14532d">• Kiraz Merkez Açısı: 35 x 4° = 140°</text>\n  <text x="520" y="158" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Kontrol: 120° + 100° + 140° = 360° (Tam Daire)</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Ters Dönüşüm (EBOB Yöntemi):</text>\n  <text x="520" y="204" text-anchor="middle" font-size="10" fill="#14532d">Açılar 120°, 100°, 140° ise EBOB(120,100,140) = 20°</text>\n  <text x="520" y="222" text-anchor="middle" font-size="10" font-weight="bold" fill="#14532d">Sayılar: Elma = 6k, Armut = 5k, Kiraz = 7k (Toplam 18k)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e293b">GRAFİK TÜRLERİNİN ÜSTÜN VE ZAYIF YÖNLERİ (KARŞILAŞTIRMA)</text>\n  <rect x="20" y="44" width="210" height="196" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="125" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">1. Çizgi Grafiği</text>\n  <text x="125" y="90" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Üstün Yönü (+):</text>\n  <text x="125" y="106" text-anchor="middle" font-size="10" fill="#713f12">Bir verinin zamana bağlı</text>\n  <text x="125" y="122" text-anchor="middle" font-size="10" fill="#713f12">sürekli değişimini, artış ve</text>\n  <text x="125" y="138" text-anchor="middle" font-size="10" fill="#713f12">azalış eğilimini en iyi gösterir.</text>\n  <text x="125" y="164" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">Zayıf Yönü (-):</text>\n  <text x="125" y="180" text-anchor="middle" font-size="10" fill="#713f12">Verilerin bütün içindeki</text>\n  <text x="125" y="196" text-anchor="middle" font-size="10" fill="#713f12">yüzde veya oranını</text>\n  <text x="125" y="212" text-anchor="middle" font-size="10" fill="#713f12">doğrudan göstermez.</text>\n\n  <rect x="245" y="44" width="210" height="196" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#0e7490">2. Sütun Grafiği</text>\n  <text x="350" y="90" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Üstün Yönü (+):</text>\n  <text x="350" y="106" text-anchor="middle" font-size="10" fill="#164e63">Farklı veri gruplarının</text>\n  <text x="350" y="122" text-anchor="middle" font-size="10" fill="#164e63">sayısal miktarlarını birbiriyle</text>\n  <text x="350" y="138" text-anchor="middle" font-size="10" fill="#164e63">karşılaştırmada en uygundur.</text>\n  <text x="350" y="164" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">Zayıf Yönü (-):</text>\n  <text x="350" y="180" text-anchor="middle" font-size="10" fill="#164e63">Parçanın bütün içindeki</text>\n  <text x="350" y="196" text-anchor="middle" font-size="10" fill="#164e63">payını görmek için ek</text>\n  <text x="350" y="212" text-anchor="middle" font-size="10" fill="#164e63">toplama işlemi gerektirir.</text>\n\n  <rect x="470" y="44" width="210" height="196" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="575" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">3. Daire Grafiği</text>\n  <text x="575" y="90" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Üstün Yönü (+):</text>\n  <text x="575" y="106" text-anchor="middle" font-size="10" fill="#581c87">Bir bütünün parçaları</text>\n  <text x="575" y="122" text-anchor="middle" font-size="10" fill="#581c87">arasındaki oranı ve yüzde</text>\n  <text x="575" y="138" text-anchor="middle" font-size="10" fill="#581c87">dağılımı en iyi gösterir.</text>\n  <text x="575" y="164" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">Zayıf Yönü (-):</text>\n  <text x="575" y="180" text-anchor="middle" font-size="10" fill="#581c87">Toplam miktar verilmezse</text>\n  <text x="575" y="196" text-anchor="middle" font-size="10" fill="#581c87">sadece açılardan gerçek</text>\n  <text x="575" y="212" text-anchor="middle" font-size="10" fill="#581c87">veri sayısı bilinemez!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#1e293b">OLASILIĞA GİRİŞ: DENEY · ÇIKTI · OLASI DURUMLAR (M.8.5.1.1 &amp; M.8.5.1.2)</text>\n  <rect x="20" y="44" width="320" height="196" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#be123c">Temel Olasılık Kavramları</text>\n  <text x="180" y="90" text-anchor="middle" font-size="11" fill="#881337">• Deney: Sonucu merak edilen rastgele işlem</text>\n  <text x="180" y="108" text-anchor="middle" font-size="10" fill="#9f1239">(Örnek: Havaya zar atılması, torbadan top çekilmesi)</text>\n  <text x="180" y="130" text-anchor="middle" font-size="11" fill="#881337">• Çıktı: Deneyde elde edilebilecek her bir sonuç</text>\n  <text x="180" y="152" text-anchor="middle" font-size="11" fill="#881337">• Tüm Olası Durumlar (Örnek Uzay): Çıktıların tamamı</text>\n  <text x="180" y="170" text-anchor="middle" font-size="10" fill="#9f1239">(Zarda: {1, 2, 3, 4, 5, 6} → 6 olası durum vardır)</text>\n  <text x="180" y="192" text-anchor="middle" font-size="11" fill="#881337">• Olay: Çıktılar arasından istenen koşula uyanlar</text>\n  <text x="180" y="212" text-anchor="middle" font-size="10" font-weight="bold" fill="#be123c">(Asal gelme olayı çıktıları: {2, 3, 5} → 3 eleman)</text>\n\n  <rect x="360" y="44" width="320" height="196" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">Olasılık Karşılaştırması (Torba Örneği)</text>\n  <text x="520" y="90" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">Torbada: 5 Kırmızı, 3 Mavi, 3 Sarı Özdeş Top</text>\n  <text x="520" y="112" text-anchor="middle" font-size="11" fill="#166534">• Tüm olası durumların sayısı = 5 + 3 + 3 = 11</text>\n  <text x="520" y="136" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">• Daha Fazla Olasılıklı: Kırmızı gelmesi (5 top)</text>\n  <text x="520" y="160" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">• Eşit Olasılıklı: Mavi (3) ile Sarı (3) gelmesi</text>\n  <text x="520" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">• Daha Az Olasılıklı: Mavi (3), Kırmızıya (5) göre az</text>\n  <text x="520" y="214" text-anchor="middle" font-size="10" fill="#14532d">Not: 11 özdeş topun her birinin çekilme şansı eşittir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
